128	/// Render a TOON document string from its parts.
129	pub(crate) fn render(
130	    type_name: &str,
131	    fields: &[String],
132	    rows: &[Vec<Value>],
133	    total_count: Option<usize>,
134	    hints: &[String],
135	    max_cell_len: usize,
136	) -> String {
137	    let row_count = rows.len();
138	    let field_count = fields.len();
139	
140	    #[cfg(debug_assertions)]
141	    for row in rows {
142	        debug_assert!(
143	            row.len() == field_count,
144	            "row length {} does not match field count {field_count} (fields: {fields:?})",
145	            row.len()
146	        );
147	    }
148	
149	    let capacity = 60 + row_count * (field_count * 12 + 10) + hints.len() * 60;
150	    let mut out = String::with_capacity(capacity);
151	
152	    // type_name[count]{field,field,...}:
153	    out.push_str(&sanitize_header_token(type_name));
154	    out.push('[');
155	    out.push_str(&row_count.to_string());
156	    out.push_str("]{");
157	    for (i, field) in fields.iter().enumerate() {
158	        if i > 0 {
159	            out.push(',');
160	        }
161	        out.push_str(&sanitize_header_token(field));
162	    }
163	    out.push_str("}:\n");
164	
165	    // rows
166	    for row in rows {
167	        out.push_str("  ");
168	        for i in 0..field_count {
169	            if i > 0 {
170	                out.push(',');
171	            }
172	            match row.get(i) {
173	                Some(Value::Str(s)) => {
174	                    if s.len() <= max_cell_len {
175	                        out.push_str(&escape_value(s));
176	                    } else {
177	                        let truncated = michi_truncate::truncate_inline(s, max_cell_len, "full=true");
178	                        out.push_str(&escape_value(&truncated));
179	                    }
180	                }
181	                Some(Value::Int(n)) => {
182	                    let _ = write!(out, "{n}");
183	                }
184	                Some(Value::Float(f)) => {
185	                    if f.is_nan() || f.is_infinite() {
186	                        // NaN and Inf are not valid TOON scalars — render as quoted strings
187	                        let s = f.to_string();
188	                        let _ = write!(out, "\"{s}\"");
189	                    } else {
190	                        let _ = write!(out, "{f}");
191	                    }
192	                }
193	                Some(Value::Bool(b)) => out.push_str(if *b { "true" } else { "false" }),
194	                Some(Value::Null) | None => {} // Null or missing cell → empty
195	            }
196	        }
197	        out.push('\n');
198	    }
199	
200	    // totalCount
201	    if let Some(total) = total_count {
202	        out.push_str("totalCount: ");
203	        out.push_str(&total.to_string());
204	        out.push('\n');
205	    }
206	
207	    // help[N]: hints
208	    if !hints.is_empty() {
209	        out.push_str("help[");
210	        out.push_str(&hints.len().to_string());
211	        out.push_str("]:\n");
212	        for hint in hints {
213	            out.push_str("  ");
214	            out.push_str(&sanitize_hint(hint));
215	            out.push('\n');
216	        }
217	    }
218	
219	    out
220	}
