4	//! # michi-toon
5	//!
6	//! Token-Optimized Object Notation (TOON) format renderer and parser for michi and AXI.
7	
8	mod escape;
9	pub(crate) mod render;
10	
11	pub use escape::{escape_value, escape_value_quoted};
12	pub use render::Value;
13	
14	/// Error returned by [`ToonOptions::validate()`] when structural invariants are violated.
15	#[derive(Debug, Clone, PartialEq)]
16	#[non_exhaustive]
17	pub enum ToonError {
18	    /// `type_name` contains a structural character (`[`, `]`, `{`, `}`, `\n`, `\r`).
19	    InvalidTypeName {
20	        /// The offending name.
21	        name: String,
22	    },
23	    /// A field name contains a structural character (`,`, `{`, `}`, `\n`, `\r`).
24	    InvalidFieldName {
25	        /// The offending field name.
26	        name: String,
27	    },
28	    /// Row `row_index` has `actual` values but `fields` declares `expected`.
29	    RowLengthMismatch {
30	        /// Zero-based index of the mismatched row.
31	        row_index: usize,
32	        /// Number of fields declared in the header.
33	        expected: usize,
34	        /// Actual number of values in the row.
35	        actual: usize,
36	    },
37	    /// An item in [`list()`] could not be rendered as a TOON row.
38	    ///
39	    /// Items must serialize to a JSON object (`serde_json::Value::Object`).
40	    /// Scalars, arrays, and `null` values cannot be represented as TOON rows.
41	    InvalidItem {
42	        /// Zero-based index of the invalid item.
43	        row_index: usize,
44	        /// Reason why the item is invalid.
45	        reason: String,
46	    },
47	}
48	
49	impl std::fmt::Display for ToonError {
50	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
51	        match self {
52	            Self::InvalidTypeName { name } => {
53	                write!(f, "type_name {name:?} contains a structural character")
54	            }
55	            Self::InvalidFieldName { name } => {
56	                write!(f, "field {name:?} contains a structural character")
57	            }
58	            Self::RowLengthMismatch { row_index, expected, actual } => {
59	                write!(f, "row {row_index} has {actual} values but {expected} fields declared")
