117	    /// Validate structural invariants before rendering.
118	    ///
119	    /// [`render_toon()`] sanitizes bad input gracefully; call this when you
120	    /// need explicit error signals. Caller opt-in for direct
121	    /// [`render_toon()`] usage — not called automatically there. See
122	    /// `PRINCIPLES.md` §1 (invariant policy).
123	    ///
124	    /// # Errors
125	    ///
126	    /// Returns [`ToonError::InvalidTypeName`] if `type_name` contains a
127	    /// structural character, [`ToonError::InvalidFieldName`] if any field name
128	    /// contains a structural character, or [`ToonError::RowLengthMismatch`] if
129	    /// any row's length differs from `fields.len()`.
130	    pub fn validate(&self) -> Result<(), ToonError> {
131	        // type_name: all STRUCTURAL chars are invalid (brackets/braces/comma/newlines)
132	        if self.type_name.chars().any(|c| escape::STRUCTURAL.contains(&c)) {
133	            return Err(ToonError::InvalidTypeName { name: self.type_name.clone() });
134	        }
135	        for field in &self.fields {
136	            // field names: comma and braces break the `{a,b,c}` header grammar;
137	            // brackets (`[`, `]`) are also replaced by sanitize_header_token so
138	            // we reject them here too for consistency with the sanitizer.
139	            if field.chars().any(|c| escape::STRUCTURAL.contains(&c)) {
140	                return Err(ToonError::InvalidFieldName { name: field.clone() });
141	            }
142	        }
143	        for (i, row) in self.rows.iter().enumerate() {
144	            if row.len() != self.fields.len() {
145	                return Err(ToonError::RowLengthMismatch {
146	                    row_index: i,
147	                    expected: self.fields.len(),
148	                    actual: row.len(),
149	                });
150	            }
151	        }
152	        Ok(())
153	    }
154	}
