194	/// Build and render a TOON document from a slice of `Serialize`-able items.
195	///
196	/// Returns the rendered TOON string on success. Returns `Err` if any item
197	/// does not serialize to a JSON object (e.g. a bare integer or string slice)
198	/// — use only with homogeneous struct slices.
199	///
200	/// Requires the `serde` feature.
201	///
202	/// # Errors
203	///
204	/// Returns [`ToonError::InvalidItem`] if an item fails to serialize or does
205	/// not produce a JSON object (struct or map required). Returns
206	/// [`ToonError::InvalidTypeName`] or [`ToonError::InvalidFieldName`] if
207	/// `type_name` or a serialized field name contains a structural character
208	/// (`[`, `]`, `{`, `}`, `,`, `\n`, `\r`).
209	#[cfg(feature = "serde")]
210	pub fn list<T: serde::Serialize>(type_name: impl Into<String>, items: &[T]) -> Result<String, ToonError> {
211	    let type_name = type_name.into();
212	    let mut fields: Vec<String> = Vec::new();
213	    let mut rows: Vec<Vec<Value>> = Vec::with_capacity(items.len());
214	    for (row_index, item) in items.iter().enumerate() {
215	        let obj = match serde_json::to_value(item) {
216	            Ok(serde_json::Value::Object(map)) => map,
217	            Ok(_) => {
218	                return Err(ToonError::InvalidItem {
219	                    row_index,
220	                    reason: "item is not a JSON object (struct or map required)".into(),
221	                });
222	            }
223	            Err(e) => {
224	                return Err(ToonError::InvalidItem { row_index, reason: e.to_string() });
225	            }
226	        };
227	        if fields.is_empty() && !obj.is_empty() {
228	            fields = obj.keys().cloned().collect();
229	        }
230	        rows.push(fields.iter().map(|f| json_value_to_toon_value(obj.get(f))).collect());
231	    }
232	    let opts = ToonOptions { type_name, fields, rows, total_count: None, hints: Vec::new(), max_cell_len: 200 };
233	    opts.validate()?;
234	    Ok(render_toon(&opts))
235	}
